-- Seis cursos base globales (community_id NULL) para el aula de capacitación:
-- asambleas y comité (Ley 21.442), control de acceso, encomiendas, incendios y
-- evacuación, residuos y aseo, y atención a residentes. Idempotente: UUID fijos
-- y actualización por id. La lección y la versión 1 publicada quedan con
-- el mismo contenido, porque el aula muestra training_lessons y la evaluación
-- lee training_module_versions.

INSERT INTO public.training_modules (
  id, title, description, target_audience, is_active, community_id, created_by, embed_url,
  learning_objectives, estimated_minutes, quality_version, version_number, quality_score,
  completion_mode, embed_allowed_origin, published_at, updated_at
) VALUES
  ('4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c104', $title$Asambleas y comité según la Ley 21.442$title$, $desc$Curso para que administración prepare cada asamblea de la comunidad con citación, quórum, votación y acta conforme a la Ley 21.442 y su reglamento, y para separar con claridad el rol del comité y el de la administración en la convivencia del condominio.$desc$, 'admin', true, NULL, NULL, NULL,
   '["Distinguir qué se trata en una asamblea ordinaria y qué solo en una extraordinaria.","Citar, verificar el quórum y validar los votos, también en sesiones telemáticas o mixtas.","Dejar un acta completa y separar lo que decide la asamblea, lo que hace el comité y lo que ejecuta la administración."]'::jsonb, 45, 6, 1, 100, 'interactive', NULL, now(), now()),
  ('4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c105', $title$Control de acceso y visitas$title$, $desc$Entrenamiento para que conserjería identifique, confirme con el residente y deje constancia de cada visita, proveedor y delivery en el acceso, actúe ante situaciones sospechosas sin enfrentar y pida solo los datos personales necesarios.$desc$, 'concierge', true, NULL, NULL, NULL,
   '["Identificar a quien llega y confirmar con la unidad antes de abrir.","Aplicar el criterio correcto a proveedores, técnicos, delivery y trabajadores frecuentes.","Actuar ante una situación sospechosa sin enfrentar y pedir solo los datos necesarios."]'::jsonb, 45, 6, 1, 100, 'interactive', NULL, now(), now()),
  ('4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c106', $title$Recepción y entrega de encomiendas$title$, $desc$Entrenamiento para que conserjería reciba cada encomienda y paquete, lo anote, avise al residente, lo custodie y lo entregue con verificación, y maneje paquetes dañados, perecibles y reclamos sin culpar a nadie.$desc$, 'concierge', true, NULL, NULL, NULL,
   '["Recibir y anotar cada paquete con su estado, ubicación y hora.","Avisar al residente en privado y entregar solo con verificación.","Manejar paquetes dañados, perecibles y reclamos con lo que dice el sistema."]'::jsonb, 45, 6, 1, 100, 'interactive', NULL, now(), now()),
  ('4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c107', $title$Prevención de incendios y evacuación$title$, $desc$Formación para residentes, conserjería y administración: prevenir un incendio cada día, conocer extintores, red húmeda y red seca, saber qué hace cada rol al detectar humo o fuego, evacuar al punto de encuentro y apoyar a personas con movilidad reducida.$desc$, 'all', true, NULL, NULL, NULL,
   '["Mantener vías de evacuación, puertas cortafuego y equipos listos en la rutina diaria.","Actuar en los primeros minutos al detectar humo: avisar al 132, alertar y salir.","Evacuar al punto de encuentro y apoyar a personas con movilidad reducida según el plan."]'::jsonb, 45, 6, 1, 100, 'interactive', NULL, now(), now()),
  ('4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c108', $title$Residuos, reciclaje y aseo de espacios comunes$title$, $desc$Entrenamiento para que conserjería mantenga la sala de basura y el aseo de los espacios comunes: horarios de retiro, separación para reciclar, residuos peligrosos o voluminosos, control de plagas y avisos a la comunidad sin culpar a nadie.$desc$, 'concierge', true, NULL, NULL, NULL,
   '["Cumplir los horarios de retiro y mantener limpia la sala de basura.","Orientar la separación para reciclar y manejar residuos peligrosos y voluminosos con seguridad.","Detectar plagas y comunicar a la comunidad sin culpar ni exponer a nadie."]'::jsonb, 45, 6, 1, 100, 'interactive', NULL, now(), now()),
  ('4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c109', $title$Atención a residentes y manejo de conflictos$title$, $desc$Curso para administración y conserjería: escuchar y desescalar, informar sin tomar partido, dejar constancia y derivar a administración los conflictos entre vecinos por ruido, mascotas o estacionamientos, con claridad sobre los límites del rol.$desc$, 'all', true, NULL, NULL, NULL,
   '["Escuchar, desescalar y ofrecer un paso siguiente concreto.","Dejar constancia de los hechos y derivar a administración sin tomar partido.","Manejar ruido, mascotas y estacionamientos dentro de los límites del rol."]'::jsonb, 45, 6, 1, 100, 'interactive', NULL, now(), now())
