INSERT INTO public.training_lessons (id, module_id, title, content, order_index) VALUES
  ('9f6a1b41-4e1b-4472-8b11-bf3b98600104', '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c104', 'Clase principal', $course$[{"id":"asamblea-proposito","title":"La asamblea decide, el comité representa y la administración ejecuta","eyebrow":"Inicio","layout":"opening","lead":"La Ley 21.442 fija quién cita, cuánto quórum se necesita y cómo queda constancia. Seguirla protege los acuerdos de toda la comunidad.","bullets":["La asamblea de copropietarios es el principal órgano de decisión del condominio (art. 13).","El comité de administración representa a la asamblea, salvo en las materias reservadas a sesión extraordinaria que no le hayan sido delegadas (art. 17).","El administrador cuida los bienes comunes, rinde cuenta y cita a asamblea cuando el presidente del comité no lo hace (arts. 16, 20 y 21)."],"visual_theme":"ink","notes":"Pide recordar la última asamblea del edificio: quién citó, cuántos llegaron y dónde quedó el acta. Usa esas respuestas para mostrar qué parte del curso las ordena."},{"id":"asamblea-tipos","title":"Ordinaria o extraordinaria: qué se trata en cada una","eyebrow":"Tipos de sesión","layout":"framework","lead":"El tipo de sesión no lo elige la prisa: lo define la materia. Una materia mal ubicada deja el acuerdo abierto a impugnación.","bullets":["Ordinaria: al menos una vez al año. Cuenta documentada y balance, elección del comité, designación o remoción del administrador y otros asuntos de interés común (art. 14).","Extraordinaria: cuando lo exijan las necesidades del condominio o la pidan el comité o copropietarios con al menos el 10% de los derechos. Solo se tratan los temas de la citación.","Solo en extraordinaria, entre otras: modificar el reglamento de copropiedad, gastos extraordinarios que superen seis cuotas de gasto común ordinario del condominio en doce meses, obras y cambios de destino en bienes comunes (art. 14).","Si la materia no está en la citación, no se vota. Se registra la inquietud y se agenda para una próxima sesión."],"visual_theme":"copper","notes":"Lee en voz alta dos materias del art. 14 y pide clasificarlas. Corrige si alguien propone votar un tema que no venía en la citación aunque haya consenso en la sala.","activity":{"type":"knowledge_check","prompt":"En la asamblea ordinaria anual, un grupo propone modificar el reglamento de copropiedad para regular el uso del quincho. ¿Qué corresponde?","options":["Votarla en la misma ordinaria si la apoya la mayoría de los asistentes","Tratarla en una sesión extraordinaria citada con esa materia, o por consulta por escrito con sesión informativa previa","Que el comité la apruebe por su cuenta y la informe en la próxima asamblea","Resolverla con una encuesta en el grupo de mensajería del edificio"],"correctIndex":1,"explanation":"La modificación del reglamento de copropiedad es materia de sesión extraordinaria (art. 14) y solo se vota si figura en la citación. El art. 15 permite también la consulta por escrito, con sesión informativa previa y el quórum que exige la materia."}},{"id":"asamblea-citacion","title":"Citar bien: quién, cómo y con cuánta anticipación","eyebrow":"Convocatoria","layout":"process","lead":"Una citación mal comunicada pone en duda todo lo que se acuerde después, aunque la sesión haya salido bien.","bullets":["Cita el comité, a través de su presidente. Si no lo hace, cita el administrador (art. 16).","Se envía a todos los copropietarios, personalmente, por carta certificada o al correo inscrito en el registro de copropietarios, con al menos cinco días y no más de quince de anticipación (art. 16).","La citación indica fecha, hora, modalidad presencial, telemática o mixta, lugar o enlace, y cada materia que se tratará.","Si la piden copropietarios con el 10% de los derechos, la citación debe enviarse dentro de diez días corridos desde que se recibe la petición (DS 7 de 2025, art. 15)."],"role_cards":[{"role":"Presidencia del comité","responsibility":"Cita y preside la asamblea","action":"Aprueba la citación con todas las materias y confirma que salió a cada copropietario"},{"role":"Administración","responsibility":"Mantiene el registro de copropietarios al día","action":"Prepara el envío, guarda el respaldo y cita si la presidencia no lo hace"}],"visual_theme":"sage","notes":"Toma una fecha de asamblea y pide calcular el primer y el último día válidos para enviar la citación. Revisa que la lista de materias sea concreta y no diga solo varios."},{"id":"asamblea-quorum","title":"Quórum: cuántos deben estar y cuántos deben aprobar","eyebrow":"Quórum del art. 15","layout":"framework","lead":"Se cuentan derechos, no personas. Primero se verifica el quórum para sesionar y después el quórum para aprobar cada acuerdo.","bullets":["Ordinaria: se constituye con asistentes que representen al menos el 33% de los derechos. Aprueba la mayoría absoluta de los asistentes.","Extraordinaria de mayoría absoluta: se constituye con la mayoría absoluta de los derechos del condominio y aprueba con mayoría absoluta de los derechos.","Extraordinaria de mayoría reforzada: se constituye con al menos el 66% de los derechos y aprueba con el 66% de los derechos.","Cada copropietario tiene un voto, proporcional a sus derechos en los bienes comunes. El administrador no puede representar a ningún copropietario (art. 15)."],"visual_theme":"amber","notes":"Muestra la lista de asistencia con porcentajes de derechos y pide sumar. Insiste en que cien personas presentes no garantizan quórum si sus derechos no alcanzan.","activity":{"type":"knowledge_check","prompt":"Al iniciar una asamblea ordinaria, los asistentes suman el 28% de los derechos del condominio. ¿Qué haces?","options":["Sesionar igual, porque en la ordinaria basta con quienes asistan","Sesionar y dejar los acuerdos sujetos a ratificación posterior","No constituir la sesión, dejar constancia de la asistencia y reprogramar o usar la consulta por escrito","Sumar como presentes a quienes enviaron un correo de apoyo antes de la sesión"],"correctIndex":2,"explanation":"La ordinaria exige asistentes con al menos el 33% de los derechos para constituirse (art. 15). Sin ese quórum no hay sesión válida. Se deja constancia y se reprograma, o se usa la consulta por escrito; si los quórum no se reúnen, la ley permite acudir al juez (art. 16)."}},{"id":"asamblea-telematica","title":"Asambleas en línea o mixtas","eyebrow":"Sesiones telemáticas","layout":"framework","lead":"Conectarse por video es válido si el reglamento de copropiedad lo permite y si cada voto se puede atribuir a una persona identificada.","bullets":["Las sesiones pueden ser presenciales, telemáticas o mixtas. La participación virtual debe estar acordada en el reglamento de copropiedad (arts. 15 y 16).","El medio elegido debe permitir participar y votar de forma efectiva y simultánea, y funcionar en distintos dispositivos (DS 7 de 2025, art. 16).","El comité identifica a cada asistente en línea con imagen y voz al acreditarse y al votar. En una sesión mixta, esa regla aplica a quienes se conectan.","No se puede exigir dónde esté físicamente quien se conecta. El lugar de la sesión es el domicilio del condominio."],"visual_theme":"ink","notes":"Pregunta qué plataforma usa la comunidad y cómo se verificaría imagen y voz al votar. Si el reglamento de copropiedad no contempla la participación virtual, deriva esa reforma a una extraordinaria."},{"id":"asamblea-escenario","title":"Votación en una asamblea mixta","eyebrow":"Práctica","layout":"scenario","lead":"Un voto que no se puede atribuir a una persona identificada no se cuenta. Mejor una votación más lenta que un acuerdo en duda.","bullets":["Sesión extraordinaria mixta para aprobar el cambio de la bomba de agua, un gasto que supera seis cuotas de gasto común ordinario en doce meses.","Hay 40 personas en la sala y 25 conectadas. Tres de ellas tienen la cámara apagada y votan por el chat.","Alguien propone contar los votos del chat para no alargar la sesión."],"visual_theme":"amber","notes":"Pide la acción concreta frente a los tres votos por chat y quién la ejecuta. La respuesta correcta identifica con imagen y voz y deja constancia en el acta.","activity":{"type":"scenario","prompt":"¿Cómo tratas los votos de las tres personas con la cámara apagada?","options":["Los cuentas: el chat deja un registro escrito del voto","Los cuentas solo si no cambian el resultado de la votación","Suspendes la sesión completa hasta que todos tengan cámara","Pides que enciendan cámara y micrófono para identificarse al votar; si no es posible, el voto no se contabiliza y queda constancia en el acta"],"correctIndex":3,"explanation":"El DS 7 de 2025 (art. 16) exige identificar a quien participa en línea con imagen y voz simultáneamente, al acreditarse y al votar. Las votaciones telemáticas o mixtas quedan registradas en el acta. No hace falta suspender la sesión."}},{"id":"asamblea-acta","title":"El acta: lo que no queda escrito no se puede cumplir","eyebrow":"Actas","layout":"process","lead":"El acta es el registro y la prueba del acuerdo. Si falta el quórum o la firma, quien deba ejecutarlo no tiene respaldo.","bullets":["Levanta el acta el presidente del comité o quien designe la asamblea. Incluye cada acuerdo con su quórum de constitución y de aprobación (art. 15).","Va en un libro de actas foliado, en papel o digital, que asegure su respaldo.","Se firma, presencial o electrónicamente, dentro de los treinta días siguientes al acuerdo, por todos los miembros del comité o por quienes designe la asamblea. El presidente del comité custodia el libro.","En las sesiones de mayoría reforzada y en las que modifican el reglamento de copropiedad debe asistir un notario, que certifica el acta (art. 15)."],"visual_theme":"sage","notes":"Revisa un acta real o de ejemplo y pide marcar si tiene quórum por acuerdo, firmas y fecha. Recuerda el plazo de treinta días para firmar."},{"id":"asamblea-roles","title":"Comité y administración: quién hace qué","eyebrow":"Roles","layout":"comparison","lead":"Cuando cada órgano sabe qué le toca, la comunidad dedica la asamblea a decidir y no a discutir quién debía haberlo hecho.","bullets":["El comité es impar, de tres a cinco miembros salvo el caso del art. 23, dura lo que fije la asamblea con un máximo de tres años y acuerda por la mitad más uno de sus miembros (art. 17).","El administrador rinde cuenta documentada al comité cada mes y a la asamblea en cada ordinaria, con los documentos disponibles al menos 24 horas antes (art. 21). No integra el comité (art. 18).","Las solicitudes anotadas en el libro de novedades se responden en un máximo de veinte días corridos (art. 17).","No uses la asamblea para exponer a una unidad ni sus montos: los temas se presentan como asuntos de la comunidad y lo individual se conversa en privado."],"role_cards":[{"role":"Asamblea","responsibility":"Decide las materias de la comunidad","action":"Vota con el quórum que exige cada materia"},{"role":"Comité de administración","responsibility":"Representa a la asamblea entre sesiones","action":"Cita, conduce, firma el acta y supervisa a la administración"},{"role":"Administración","responsibility":"Ejecuta los acuerdos y cuida los bienes comunes","action":"Rinde cuenta documentada y mantiene el registro y los respaldos"}],"visual_theme":"copper","notes":"Pide ubicar tres tareas reales en el órgano correcto: aprobar una obra, contratar la mantención del ascensor y responder el libro de novedades. Corrige cualquier exposición de unidades o montos."},{"id":"asamblea-cierre","title":"Antes de cerrar la asamblea","eyebrow":"Transferencia","layout":"checklist","lead":"Una asamblea termina bien cuando cualquier copropietario puede leer el acta y saber qué se acordó, con qué quórum y quién lo ejecuta.","bullets":["La citación salió a todos dentro del plazo y con cada materia.","El quórum de constitución y de aprobación quedó anotado por acuerdo.","El acta tiene responsable de firma, plazo y custodio del libro."],"visual_theme":"ink","notes":"Recorre la lista con la próxima asamblea del edificio y acuerda quién revisa cada punto antes de enviar la citación.","activity":{"type":"checklist","prompt":"Confirma que puedes aplicar estos pasos en la próxima asamblea:","items":["Clasificar cada materia como ordinaria o extraordinaria antes de citar","Enviar la citación a todos los copropietarios entre cinco y quince días antes","Verificar el quórum por derechos y validar los votos en línea con imagen y voz","Dejar en el acta cada acuerdo con su quórum y firmarla dentro de treinta días"],"explanation":"Con estos cuatro pasos los acuerdos de la asamblea quedan respaldados y la comunidad puede cumplirlos."}}]$course$, 0),
  ('9f6a1b41-4e1b-4472-8b11-bf3b98600105', '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c105', 'Clase principal', $course$[{"id":"acceso-proposito","title":"El control de acceso cuida a quienes viven aquí","eyebrow":"Inicio","layout":"opening","lead":"Cada ingreso se identifica, se confirma con quien vive en la unidad y queda anotado. Así se protege a la comunidad sin tratar a nadie como sospechoso.","bullets":["Nadie entra sin que un residente de la unidad lo confirme o sin una autorización previa en el sistema.","Se pide solo el dato que define el protocolo y se guarda en el sistema del edificio, no en libretas sueltas ni en el teléfono personal.","El trato es igual para todas las personas. El criterio es el protocolo, no la apariencia de quien llega."],"visual_theme":"ink","notes":"Pregunta qué ingreso del último turno fue más difícil de manejar. Úsalo para mostrar que el protocolo da una respuesta igual para todos."},{"id":"acceso-procedimiento","title":"Identificar, confirmar y dejar constancia","eyebrow":"Procedimiento","layout":"process","lead":"Cuatro pasos, en este orden, para cada visita. Saltarse la confirmación es la forma más común de abrir a quien no corresponde.","bullets":["Saluda y pregunta a quién visita y a qué unidad.","Confirma con el residente por el canal del edificio, ya sea citófono, app o llamada, antes de abrir.","Anota nombre, unidad y hora de ingreso y, si el protocolo lo pide, documento o patente.","Indica el camino y anota la hora de salida."],"role_cards":[{"role":"Conserjería","responsibility":"Verifica cada ingreso","action":"Confirma con la unidad antes de abrir y anota entrada y salida"},{"role":"Residente","responsibility":"Autoriza a sus visitas","action":"Avisa con anticipación o responde el citófono"},{"role":"Administración","responsibility":"Define el protocolo de ingreso","action":"Fija qué datos se piden, quién los ve y cuánto tiempo se guardan"}],"visual_theme":"sage","notes":"Simula una visita en voz alta y detén el ejercicio si se abre antes de confirmar con la unidad. Pide decir exactamente qué se anota."},{"id":"acceso-proveedores","title":"Proveedores, técnicos y repartidores en el acceso","eyebrow":"Casos frecuentes","layout":"framework","lead":"Un uniforme o una credencial no reemplazan la confirmación. Cada tipo de visita tiene su forma de validarse.","bullets":["Proveedor del edificio: valida contra el aviso o la orden de trabajo de administración. Si no hay aviso, consulta antes de dar acceso.","Técnico para una unidad: se confirma con el residente igual que cualquier visita.","Delivery: se entrega en portería o el residente baja, según el protocolo. No se presta una llave o tarjeta para subir.","Trabajadores frecuentes de una unidad: autorización escrita del residente en el sistema, con vigencia y horario."],"visual_theme":"copper","notes":"Pide validar tres llegadas distintas: gasfíter para el 304, empresa de ascensores sin aviso y repartidor de comida. Revisa que cada una tenga su confirmación.","activity":{"type":"knowledge_check","prompt":"Llega un técnico con uniforme de la empresa de ascensores y dice que viene a una revisión. No hay aviso en el sistema. ¿Qué haces?","options":["Lo dejas pasar: el uniforme y la credencial son suficientes","Le pides esperar y confirmas con administración o con la empresa en el contacto registrado antes de dar acceso","Le dices que vuelva otro día sin consultar a nadie","Lo dejas pasar y avisas a administración al final del turno"],"correctIndex":1,"explanation":"Sin aviso, la confirmación con administración o con el contacto registrado de la empresa es lo que valida el ingreso. Rechazarlo sin consultar puede atrasar una mantención necesaria; dejarlo pasar sin confirmar abre el edificio a cualquiera con uniforme."}},{"id":"acceso-datos","title":"Datos personales: lo justo y en su lugar","eyebrow":"Ley 21.719","layout":"comparison","lead":"Cada dato que pides en portería debe tener un fin concreto. Pedir de más o guardarlo mal expone a residentes y visitas.","bullets":["Pide solo lo que el protocolo define. Los datos se recogen con un fin específico y se limitan a lo necesario: son los principios de finalidad y proporcionalidad de la Ley 21.719.","Anota en el sistema del edificio y evita que la pantalla quede a la vista de quien espera.","No fotografíes el carnet con tu teléfono ni compartas la lista de visitas por mensajería.","No informes a un tercero quién visitó una unidad. Si alguien lo pide, deriva a administración."],"visual_theme":"amber","notes":"Pregunta qué datos se piden hoy en portería y para qué sirve cada uno. Si un dato no tiene un uso claro, anótalo como propuesta para administración."},{"id":"acceso-escenario","title":"Alguien cruza el acceso detrás de un residente","eyebrow":"Práctica","layout":"scenario","lead":"El ingreso por arrastre por el portón es frecuente y se corta con una pregunta amable, no con una persecución.","bullets":["Un residente abre el portón peatonal con su llave.","Una persona que no conoces entra detrás, sin saludar, y camina hacia los ascensores.","El residente sigue sin mirar atrás."],"visual_theme":"amber","notes":"Pide la frase exacta con que abordarías a la persona. La respuesta correcta pregunta con cortesía, confirma con la unidad y no persigue ni retiene.","activity":{"type":"scenario","prompt":"¿Qué haces?","options":["Lo sigues hasta el ascensor y le exiges que se identifique","Lo dejas: si entró con un residente, seguramente viene con él","Lo abordas con cortesía: \"Buenas tardes, ¿a qué departamento va?\". Confirmas con la unidad y, si no hay autorización, le pides esperar afuera y anotas lo ocurrido","Llamas de inmediato a Carabineros sin hablar con la persona"],"correctIndex":2,"explanation":"Una pregunta amable resuelve la mayoría de los casos: muchas veces es una visita que se adelantó. Confirmar con la unidad mantiene el criterio de siempre. Perseguir o retener expone a conserjería; llamar a Carabineros corresponde si hay riesgo o conducta que lo amerite."}},{"id":"acceso-sospecha","title":"Situaciones sospechosas: observar, no enfrentar","eyebrow":"Seguridad","layout":"framework","lead":"Para la seguridad de todos, sirve una descripción precisa de la conducta, la hora y el lugar. No se enfrenta ni se retiene a nadie.","bullets":["Describe conductas, no personas: qué hace, dónde, desde qué hora y hacia dónde fue.","Si hay riesgo para alguien, llama a Carabineros al 133 y avisa a administración. No intentes retener a nadie.","Usa las cámaras para seguir lo que pasa, no para difundir imágenes.","Anota el hecho en la bitácora con hora y lugar apenas sea seguro."],"visual_theme":"ink","notes":"Compara dos registros, uno con adjetivos y otro con hora, lugar y conducta. Pide reescribir el primero hasta que el turno siguiente pueda usarlo.","activity":{"type":"knowledge_check","prompt":"¿Cuál de estos registros le sirve al turno siguiente y a administración?","options":["\"Pasó un tipo raro por el estacionamiento\"","\"Persona de mal aspecto rondando el edificio\"","\"Otra vez el problema de siempre en el subterráneo\"","\"21:40: persona recorre el subterráneo -2 probando manillas de autos. Salió por el portón vehicular a las 21:46. Se avisó a administración.\""],"correctIndex":3,"explanation":"El registro útil tiene hora, lugar, conducta observada y qué se hizo. Los adjetivos sobre la apariencia no describen un hecho y pueden discriminar."}},{"id":"acceso-limites","title":"Cuando el residente no contesta o no autoriza","eyebrow":"Límites del rol","layout":"comparison","lead":"Decir que no también es atender bien, siempre que se explique el motivo y se ofrezca una salida.","bullets":["Si nadie responde, la visita espera afuera o deja un recado. Ofrece intentar de nuevo en unos minutos.","Explica con calma: \"El protocolo nos pide confirmar con la unidad antes de abrir\".","No dejes pasar por insistencia, porque conoces a la persona de vista o porque \"siempre viene\".","No decidas entre familiares o exparejas que piden entrar: deriva a administración y, si hay riesgo, llama al 133."],"role_cards":[{"role":"Conserjería","responsibility":"Aplica el protocolo de confirmación","action":"Ofrece esperar o dejar recado y anota el intento"},{"role":"Administración","responsibility":"Resuelve los casos fuera de protocolo","action":"Define autorizaciones especiales por escrito"}],"visual_theme":"copper","notes":"Practica la frase para una visita molesta que no puede entrar. Debe explicar el motivo, ofrecer una salida y no culpar al residente."},{"id":"acceso-cierre","title":"Antes de entregar el turno","eyebrow":"Transferencia","layout":"checklist","lead":"El acceso queda bien entregado cuando el turno siguiente sabe quién sigue adentro y qué autorizaciones están vigentes.","bullets":["Cada ingreso del turno tiene confirmación y hora de entrada y salida.","Las visitas que siguen adentro están identificadas.","Cualquier hecho sospechoso quedó anotado y avisado."],"visual_theme":"ink","notes":"Completa la lista con los ingresos del turno actual y pide nombrar a quién sigue en el edificio sin mirar el sistema.","activity":{"type":"checklist","prompt":"Confirma que puedes aplicar estos pasos en tu turno:","items":["Confirmar con la unidad antes de abrir a cualquier visita","Validar proveedores contra el aviso de administración","Pedir solo los datos que define el protocolo y anotarlos en el sistema","Describir hechos sospechosos con hora, lugar y conducta, sin enfrentar"],"explanation":"Así el acceso protege a la comunidad y cada decisión queda respaldada."}}]$course$, 0),
  ('9f6a1b41-4e1b-4472-8b11-bf3b98600106', '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c106', 'Clase principal', $course$[{"id":"encomienda-proposito","title":"Cada encomienda tiene dueño y un recorrido que se puede seguir","eyebrow":"Inicio","layout":"opening","lead":"Recibir, anotar, avisar, guardar y entregar con verificación evita pérdidas y discusiones. Si falta un paso, nadie puede explicar dónde quedó el paquete.","bullets":["Conserjería custodia el paquete desde que firma la guía hasta que lo entrega a quien corresponde.","El sistema del edificio es la fuente de verdad: hora, estado, ubicación y quién retiró.","El aviso al residente es privado. Las encomiendas no se exhiben ni se comentan en grupos."],"visual_theme":"ink","notes":"Pide contar un reclamo de encomienda reciente y en qué paso se perdió el rastro. Úsalo para presentar los cinco pasos del curso."},{"id":"encomienda-recepcion","title":"Recibir y anotar","eyebrow":"Recepción","layout":"process","lead":"Lo que no se revisa delante del repartidor después no se puede reclamar. La recepción toma un minuto más y ahorra horas.","bullets":["Comprueba que la unidad y el destinatario existan antes de firmar la guía.","Revisa el estado delante del repartidor: caja abierta, mojada o aplastada se anota en la guía y en el sistema.","Anota unidad, destinatario, empresa, hora y ubicación de guardado. Si el sistema lo permite, agrega una foto del paquete.","No recibas pagos contra entrega ni pagues por un residente."],"role_cards":[{"role":"Conserjería","responsibility":"Recibe y custodia","action":"Revisa el estado, anota y guarda en el lugar definido"},{"role":"Residente","responsibility":"Retira a tiempo","action":"Autoriza en el sistema a quien puede retirar por él"},{"role":"Administración","responsibility":"Define reglas de custodia","action":"Fija plazos de retiro y lugar para perecibles"}],"visual_theme":"sage","notes":"Con un paquete de ejemplo, pide decir en voz alta qué se revisa y qué se anota antes de que el repartidor se vaya."},{"id":"encomienda-aviso","title":"Avisar sin exponer","eyebrow":"Notificación","layout":"framework","lead":"El aviso llega solo a quien debe retirar, con lo justo para que venga a buscar su paquete.","bullets":["Notifica al residente por el canal del edificio apenas el paquete queda anotado.","El aviso dice empresa, hora y dónde retirar. No se publican nombres ni unidades en grupos o pizarras.","Si pasan los días que fija administración sin retiro, se reenvía el aviso en privado y se informa a administración."],"visual_theme":"copper","notes":"Pide redactar el aviso para un paquete que llegó a las 11:20. Corrige si incluye datos de otra unidad o un tono de reproche.","activity":{"type":"knowledge_check","prompt":"¿Cuál de estos avisos corresponde?","options":["Mensaje privado: \"Llegó un paquete de la empresa de envíos a las 11:20. Está en conserjería para retiro.\"","En el grupo del edificio: \"Depto 504, tiene tres paquetes acumulados, retire pronto.\"","Nota en la pizarra del hall con los nombres de quienes tienen paquetes pendientes","No avisar y esperar a que el residente pregunte"],"correctIndex":0,"explanation":"El aviso privado informa lo necesario sin exponer a nadie. Publicar unidades o nombres revela datos personales y presiona al residente frente a sus vecinos."}},{"id":"encomienda-custodia","title":"Custodia: dónde y cómo se guarda","eyebrow":"Custodia","layout":"framework","lead":"Un paquete bien guardado se encuentra en segundos, aunque lo haya recibido otro turno.","bullets":["Guarda en la bodega o casillero definido, con acceso solo del personal de turno.","Ordena por unidad y anota la ubicación en el sistema.","Perecibles y medicamentos: avisa de inmediato al residente, refrigera solo si existe un lugar designado y anota la hora.","En la entrega de turno se cuentan los paquetes pendientes contra el sistema."],"visual_theme":"ink","notes":"Pregunta dónde se guardan hoy los perecibles. Si no hay un lugar definido, anótalo como pendiente para administración."},{"id":"encomienda-entrega","title":"Entregar con verificación","eyebrow":"Entrega","layout":"process","lead":"Entregar al primero que pregunta es la forma más común de perder un paquete. La verificación protege al residente y a conserjería.","bullets":["Entrega al destinatario o a quien la unidad autorizó en el sistema.","Verifica la identidad con el medio que define el protocolo: código, carnet o confirmación en la app.","Anota quién retiró y a qué hora. El paquete queda cerrado como entregado.","No entregues a otra persona \"que se lo lleva\" si no hay una autorización anotada."],"visual_theme":"sage","notes":"Simula a un vecino que ofrece llevar el paquete del 702. La respuesta correcta pide la autorización en el sistema y ofrece avisar a la unidad."},{"id":"encomienda-escenario","title":"Paquete húmedo y con olor","eyebrow":"Práctica","layout":"scenario","lead":"Un paquete dañado se recibe con constancia o no se recibe. Lo que importa es que el estado quede escrito antes de firmar.","bullets":["Llega una caja húmeda y con olor fuerte para el 305.","El repartidor está apurado y pide que firmes sin revisar.","El residente no está en casa."],"visual_theme":"amber","notes":"Pide el orden exacto de acciones antes de firmar la guía. La respuesta correcta deja constancia del estado y avisa al residente.","activity":{"type":"scenario","prompt":"¿Qué haces?","options":["Firmas rápido para no retener al repartidor y lo revisas después","Abres la caja para ver qué se rompió","Antes de firmar anotas el estado en la guía y en el sistema, tomas una foto si es posible, lo guardas aparte y avisas al residente","Lo dejas en la puerta del 305 para que lo vea al llegar"],"correctIndex":2,"explanation":"Anotar el estado antes de firmar deja respaldo para el reclamo del residente. Abrir un paquete ajeno no corresponde y dejarlo en la puerta rompe la custodia."}},{"id":"encomienda-reclamos","title":"Reclamos: escuchar, revisar y derivar","eyebrow":"Reclamos","layout":"comparison","lead":"Ante un reclamo, el sistema habla por el turno. Se informa lo que está anotado, sin culpar a nadie.","bullets":["Escucha y pide los datos: empresa, fecha y número de seguimiento.","Revisa el sistema: hora de recepción, quién recibió, ubicación y si figura retirado.","Informa lo que dice el registro y, si no aclara el caso, deriva a administración e indica quién lo seguirá.","No culpes a otro turno ni al residente.","No prometas reponer el paquete ni asumas costos: eso lo ve administración con la empresa de transporte."],"visual_theme":"copper","notes":"Simula un reclamo de paquete que figura entregado. Pide la secuencia de revisión y corta cualquier frase que culpe a alguien.","activity":{"type":"knowledge_check","prompt":"Un residente dice que su paquete figura como entregado, pero no lo tiene. ¿Cuál es tu primer paso?","options":["Decirle que seguramente lo retiró alguien de su familia","Prometerle que el edificio lo va a reponer","Culpar al turno anterior, que lo entregó","Revisar en el sistema quién retiró, a qué hora y con qué verificación, e informarle lo que aparece"],"correctIndex":3,"explanation":"El registro de entrega muestra quién retiró y cómo se verificó. Con ese dato el residente puede revisar en su unidad o administración puede seguir el caso. Suponer, prometer o culpar no resuelve nada."}},{"id":"encomienda-cierre","title":"Antes de entregar el turno","eyebrow":"Transferencia","layout":"checklist","lead":"El turno siguiente debe poder encontrar cada paquete pendiente y saber si hay alguno dañado o perecible.","bullets":["Los pendientes del sistema coinciden con los paquetes guardados.","Perecibles y paquetes dañados están señalados.","Los reclamos abiertos tienen responsable."],"visual_theme":"ink","notes":"Cuenta con el grupo los paquetes pendientes del turno y compáralos con el sistema antes de dar por cerrado el curso.","activity":{"type":"checklist","prompt":"Confirma que puedes aplicar estos pasos en tu turno:","items":["Revisar el estado del paquete antes de firmar la guía","Anotar unidad, empresa, hora y ubicación de guardado","Avisar al residente solo por el canal privado del edificio","Entregar con verificación y anotar quién retiró"],"explanation":"Con estos pasos cada paquete se puede rastrear de la recepción a la entrega."}}]$course$, 0),
  ('9f6a1b41-4e1b-4472-8b11-bf3b98600107', '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c107', 'Clase principal', $course$[{"id":"incendio-proposito","title":"Un incendio se previene todos los días","eyebrow":"Inicio","layout":"opening","lead":"Casi todo lo que salva vidas en un incendio se hace antes: vías despejadas, equipos listos y cada persona sabiendo qué hacer cuando siente olor a humo.","bullets":["Todo condominio debe tener un plan de emergencia, con énfasis en la alerta temprana y la evacuación ante incendios (Ley 21.442, art. 40).","En conserjería debe estar el plan actualizado y un plano con las vías de evacuación, la red seca, la red húmeda y las demás instalaciones de emergencia (art. 40).","Ante fuego o humo, se llama a Bomberos al 132."],"visual_theme":"ink","notes":"Pregunta dónde está el plano de evacuación del edificio y cuál es el punto de encuentro. Si nadie lo sabe, ese es el primer pendiente."},{"id":"incendio-prevencion","title":"Prevención diaria contra incendios","eyebrow":"Antes","layout":"framework","lead":"La ronda diaria detecta lo que en un incendio bloquea la salida o alimenta el fuego.","bullets":["Pasillos, escaleras y salidas libres: sin bicicletas, cajas, muebles ni bolsas.","Puertas cortafuego cerradas, sin cuñas ni amarras que las mantengan abiertas.","Sala de basura y bodegas sin acumulación de cartones ni materiales inflamables.","Enchufes recalentados, cables a la vista u olor a quemado se informan como urgencia."],"visual_theme":"copper","notes":"Recorre mentalmente la ruta desde un piso alto hasta la salida y pide nombrar cada obstáculo que se ha visto en el último mes.","activity":{"type":"knowledge_check","prompt":"En la ronda encuentras la puerta de la escalera de emergencia trabada con un balde para ventilar. ¿Qué haces?","options":["La dejas así: ventilar también es importante","Retiras el balde, cierras la puerta, lo anotas y avisas a administración para un recordatorio general","Sacas una foto y la publicas en el grupo para que sepan quién fue","La cierras con llave para que no se vuelva a abrir"],"correctIndex":1,"explanation":"La puerta cortafuego frena el humo en la escalera, la vía de escape de todos. Se cierra y se registra. Exponer a alguien no previene, y cerrar con llave bloquearía la evacuación."}},{"id":"incendio-equipos","title":"Extintores, red húmeda y red seca","eyebrow":"Equipos","layout":"framework","lead":"Saber dónde está cada equipo y para qué sirve permite usarlo bien o dejarlo libre para Bomberos.","bullets":["Extintor: debe estar a la vista, sin obstáculos y con sello y etiqueta de mantención. Si falta o está descargado, se informa.","Red húmeda: manguera conectada al agua del edificio para un fuego que recién empieza. Úsala solo si fuiste capacitado y tienes la salida a tu espalda.","Red seca: cañería para uso de Bomberos. Su boca de alimentación en la fachada debe quedar despejada y visible.","La mantención de los sistemas de emergencia y de extinción es responsabilidad de la administración (Ley 21.442, art. 20)."],"visual_theme":"sage","notes":"Pide ubicar en el plano el extintor y la red húmeda más cercanos a la conserjería. Aclara que la red seca no la usa el personal del edificio."},{"id":"incendio-humo","title":"Al detectar humo: los primeros minutos","eyebrow":"Durante","layout":"process","lead":"Primero se avisa y se alerta. Combatir el fuego es la excepción y solo si es pequeño y hay salida segura.","bullets":["Llama al 132 con dirección, piso, qué ves y si hay personas atrapadas. Activa la alarma si existe.","Avisa a conserjería y a administración. Conserjería activa el protocolo del plan de emergencia.","Usa el extintor solo si el fuego es pequeño, fuiste capacitado y tienes la salida a tu espalda. Si no se apaga en segundos, sal.","Cierra las puertas al salir para frenar el humo. No abras una puerta que está caliente."],"role_cards":[{"role":"Residente","responsibility":"Avisa y sale","action":"Llama al 132, alerta a conserjería y baja por la escalera"},{"role":"Conserjería","responsibility":"Activa el protocolo","action":"Confirma el aviso al 132, alerta a los pisos y recibe a Bomberos"},{"role":"Administración","responsibility":"Mantiene el plan y los equipos","action":"Coordina con Bomberos y comunica a la comunidad después"}],"visual_theme":"amber","notes":"Pide ensayar la llamada al 132 en voz alta con la dirección real del edificio. Debe durar menos de treinta segundos y decir piso y si hay personas atrapadas."},{"id":"incendio-evacuar","title":"Evacuar por la escalera hasta el punto de encuentro","eyebrow":"Evacuación","layout":"process","lead":"La evacuación ordenada evita lesiones y permite a Bomberos saber quién falta.","bullets":["Baja por la escalera. No uses el ascensor durante un incendio.","Si hay humo, avanza agachado, cerca del suelo, y cúbrete nariz y boca.","Ve al punto de encuentro del plan y quédate ahí hasta que Bomberos o el encargado indiquen otra cosa.","Si no puedes salir, quédate en la unidad con la puerta cerrada, tapa las rendijas con paños y llama al 132 indicando dónde estás."],"visual_theme":"sage","notes":"Pide describir la ruta desde su lugar de trabajo o su unidad hasta el punto de encuentro, y qué harían si la escalera tiene humo."},{"id":"incendio-apoyo","title":"Personas con movilidad reducida y quienes necesitan apoyo","eyebrow":"Inclusión","layout":"framework","lead":"El plan debe decir quién necesita ayuda para salir y cómo se le ayuda. Ese dato se usa con reserva y solo para la emergencia.","bullets":["El plan de evacuación se actualiza al menos una vez al año, considerando a personas con discapacidad, movilidad reducida, infantes y quienes no hablan español (Ley 21.442, art. 40).","Conserjería conoce, con reserva, qué unidades informaron necesitar apoyo. Ese dato se usa solo para la evacuación o la emergencia (DS 7 de 2025, art. 7).","Al llegar Bomberos, se informa qué personas podrían seguir en el edificio y en qué piso.","Si no fuiste capacitado para trasladar a alguien por la escalera, acompáñalo en un lugar protegido con la puerta cerrada y avisa al 132 dónde está."],"visual_theme":"copper","notes":"Pregunta si el edificio tiene la lista de apoyo actualizada y quién la custodia. Recuerda que no se comparte por mensajería.","activity":{"type":"knowledge_check","prompt":"Una vecina del piso 7 usa silla de ruedas. Suena la alarma y el ascensor está fuera de uso. ¿Qué corresponde?","options":["Bajarla en brazos por la escalera aunque nadie esté capacitado","Seguir evacuando y dejar su caso para después","Pedirle que espere en el ascensor hasta que vuelva la energía","Acompañarla en un lugar protegido con la puerta cerrada, avisar al 132 su piso y ubicación, e informar a Bomberos al llegar"],"correctIndex":3,"explanation":"Un traslado sin capacitación puede lesionar a ambos. Lo que el plan pide es que Bomberos sepa exactamente dónde está la persona y que quede protegida del humo mientras llegan."}},{"id":"incendio-escenario","title":"Humo en el piso 5 de madrugada","eyebrow":"Práctica","layout":"scenario","lead":"De noche hay menos personas despiertas y el aviso temprano marca la diferencia. Primero se llama y se alerta.","bullets":["Son las 02:30. Un residente avisa a conserjería que sale humo por debajo de la puerta del 502.","Nadie responde en esa unidad.","Algunos vecinos del piso salen al pasillo y otros llaman al ascensor."],"visual_theme":"amber","notes":"Pide la primera acción y luego la segunda. La respuesta correcta llama al 132 antes de subir a confirmar y saca a la gente por la escalera.","activity":{"type":"scenario","prompt":"¿Qué haces primero?","options":["Subes a golpear la puerta del 502 para confirmar que hay fuego","Esperas a que administración autorice llamar a Bomberos","Llamas al 132 con dirección, piso y lo que se ve, activas la alarma y el protocolo, indicas a los vecinos que bajen por la escalera sin usar el ascensor y avisas a administración","Cortas la luz general del edificio antes de llamar"],"correctIndex":2,"explanation":"Humo saliendo de una unidad basta para llamar al 132: confirmar subiendo expone a quien sube y atrasa el aviso. Ninguna autorización se espera para llamar. El ascensor no se usa durante un incendio."}},{"id":"incendio-despues","title":"Después: volver solo cuando Bomberos lo indique","eyebrow":"Después","layout":"comparison","lead":"Terminada la emergencia, se cuida a las personas, se deja constancia y se comunica sin exponer a nadie.","bullets":["Nadie vuelve a entrar hasta que Bomberos lo autorice.","Anota hora del aviso, llegada de Bomberos, unidades afectadas y quiénes fueron atendidos.","No difundas fotos ni el número de la unidad donde se originó: administración comunica lo que corresponda.","Evita especular sobre la causa en el pasillo o en grupos de mensajería."],"visual_theme":"ink","notes":"Pide redactar en dos frases el aviso a la comunidad después de un amago. Corrige si nombra la unidad o supone una causa."},{"id":"incendio-cierre","title":"Lista de preparación ante incendios","eyebrow":"Transferencia","layout":"checklist","lead":"Estar preparado es poder responder estas preguntas sin buscar: dónde está el extintor, por dónde se sale y a quién se llama.","bullets":["Conozco la ruta de evacuación y el punto de encuentro.","Sé dónde están el extintor y la red húmeda más cercanos.","Sé que se llama al 132 y qué decir."],"visual_theme":"ink","notes":"Pide a cada participante responder la lista en voz alta con los datos reales de su edificio antes de completar el curso.","activity":{"type":"checklist","prompt":"Confirma que puedes aplicar estos pasos:","items":["Mantener pasillos, escaleras y puertas cortafuego despejados y cerrados","Llamar al 132 con dirección, piso y si hay personas atrapadas","Evacuar por la escalera, sin ascensor, hasta el punto de encuentro","Informar a Bomberos dónde puede haber personas que necesitan apoyo"],"explanation":"Con estos pasos cada rol sabe qué hacer antes, durante y después de un incendio."}}]$course$, 0),
  ('9f6a1b41-4e1b-4472-8b11-bf3b98600108', '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c108', 'Clase principal', $course$[{"id":"residuos-proposito","title":"Un espacio común limpio se cuida entre todos","eyebrow":"Inicio","layout":"opening","lead":"Horarios claros, separación correcta y avisos sin culpas mantienen la sala de basura y los espacios comunes en buen estado.","bullets":["Conserjería mantiene la rutina de aseo y la sala de basura, y orienta a los residentes.","Lo que se repite se anota y se informa a administración, que decide cómo comunicarlo.","Los avisos hablan de conductas y horarios, nunca de una unidad o una persona."],"visual_theme":"ink","notes":"Pregunta cuál es el problema de residuos más frecuente del edificio. Úsalo como hilo para el resto del curso."},{"id":"residuos-horarios","title":"Horarios de retiro y rutina de aseo","eyebrow":"Rutina","layout":"framework","lead":"Cuando el horario está claro y visible, la basura no se acumula y nadie tiene que adivinar.","bullets":["Conoce el horario de retiro del municipio o de la empresa y saca los contenedores a tiempo.","Publica los horarios de depósito que fije administración en un lugar visible y en la app.","Lava y ordena los contenedores después del retiro, según la rutina de aseo del edificio.","Si el camión no pasó, anótalo y avisa a administración para que haga el reclamo."],"visual_theme":"copper","notes":"Pide el horario de retiro del edificio y dónde está publicado. Si no está a la vista, queda como acción para el próximo turno."},{"id":"residuos-reciclaje","title":"Separar para reciclar","eyebrow":"Reciclaje","layout":"framework","lead":"Un contenedor de reciclaje contaminado con restos de comida termina en la basura común. La señalética clara evita ese error.","bullets":["Cada contenedor con su rótulo: qué va y qué no, con imágenes simples.","El material reciclable va limpio, seco y aplastado.","Si un contenedor se mezcla, retira lo evidente solo si es seguro y anótalo para un recordatorio general.","Confirma con administración qué recibe el punto limpio o el gestor del edificio, porque cambia según la comuna."],"visual_theme":"sage","notes":"Muestra tres objetos: una caja de pizza con grasa, una botella enjuagada y una pila. Pide decir dónde va cada uno según el gestor del edificio.","activity":{"type":"knowledge_check","prompt":"Un residente pregunta dónde va una caja de pizza con restos de grasa. ¿Qué le respondes?","options":["Al contenedor de cartón, tal como está","A la basura común si tiene grasa o restos de comida; la parte limpia puede ir a reciclaje si el gestor del edificio la recibe","A cualquier contenedor, porque después se separa","Que la deje en el pasillo para que conserjería decida"],"correctIndex":1,"explanation":"La grasa y los restos de comida contaminan el cartón reciclable. La respuesta orienta con amabilidad y remite a lo que recibe el gestor del edificio."}},{"id":"residuos-sala","title":"La sala de basura","eyebrow":"Sala de basura","layout":"process","lead":"Una sala de basura ordenada y cerrada evita olores, plagas y riesgo de incendio.","bullets":["Mantén la puerta cerrada y las bolsas dentro de los contenedores, nunca en el suelo.","Usa guantes y calzado cerrado. No metas la mano en una bolsa para revisar su contenido.","Limpia y desinfecta según la rutina, y anota la hora en el registro de aseo.","No acumules cartones ni objetos que puedan prender fuego."],"role_cards":[{"role":"Conserjería","responsibility":"Mantiene la sala y la rutina de aseo","action":"Limpia, ordena, anota y avisa lo que se repite"},{"role":"Administración","responsibility":"Define horarios, gestor y proveedores","action":"Coordina retiros especiales, control de plagas y avisos generales"}],"visual_theme":"amber","notes":"Pide describir el estado ideal de la sala de basura al terminar el turno y qué elementos de protección se usan."},{"id":"residuos-especiales","title":"Residuos peligrosos y voluminosos","eyebrow":"Casos especiales","layout":"comparison","lead":"Algunos residuos no pueden ir a la basura común. Conserjería orienta y protege, no los manipula sin cuidado.","bullets":["Pilas, aceite, pintura, químicos, ampolletas y aparatos eléctricos se separan. Indica al residente dónde llevarlos según lo que informe administración o el municipio.","Voluminosos como muebles o colchones se coordinan con el retiro que ofrezca el municipio o administración.","Jeringas o vidrios rotos: usa pinza o pala, un envase rígido y avisa a administración.","No dejes voluminosos en pasillos ni en la sala de basura.","No vacíes líquidos desconocidos ni mezcles productos de limpieza."],"visual_theme":"copper","notes":"Pregunta qué hacer con un colchón dejado junto al ascensor. La respuesta correcta lo traslada a un lugar que no bloquea, lo anota y pide el retiro a administración."},{"id":"residuos-plagas","title":"Plagas: detectar y avisar","eyebrow":"Plagas","layout":"framework","lead":"Una plaga se controla mejor cuando se avisa temprano y se ataca la causa: comida y basura al alcance.","bullets":["Señales: fecas, roeduras, olor o insectos en la sala de basura, shafts o bodegas.","Anota lugar, hora y lo observado, y avisa a administración para coordinar a la empresa de control.","No apliques venenos por tu cuenta ni dejes cebos donde lleguen niños o mascotas.","Tapas cerradas y nada fuera de los contenedores es la mejor prevención."],"visual_theme":"sage","notes":"Pide redactar el aviso a administración tras ver fecas de roedor en la sala de basura. Debe tener lugar, hora y observación.","activity":{"type":"knowledge_check","prompt":"Ves fecas de roedor detrás de los contenedores. ¿Qué haces?","options":["Compras veneno y lo dejas detrás de los contenedores","No dices nada para no alarmar","Avisas en el grupo del edificio que hay ratones por culpa de algunos vecinos","Anotas lugar, hora y lo observado, limpias con protección y avisas a administración para coordinar el control"],"correctIndex":3,"explanation":"El control lo coordina administración con una empresa especializada. El veneno sin control arriesga a niños y mascotas, y culpar a vecinos no resuelve la causa."}},{"id":"residuos-escenario","title":"Bolsas fuera de horario, otra vez","eyebrow":"Práctica","layout":"scenario","lead":"Cuando un problema se repite, la tentación es buscar culpables. El camino es retirar, anotar y proponer un aviso general.","bullets":["Hace una semana aparecen bolsas en el pasillo del piso 8, junto al shaft.","Un vecino te pide que publiques el número del departamento que cree responsable.","No viste quién las dejó."],"visual_theme":"amber","notes":"Pide la respuesta exacta al vecino que pide publicar la unidad. Debe reconocer la molestia, explicar el camino y no exponer a nadie.","activity":{"type":"scenario","prompt":"¿Qué haces?","options":["Retiras las bolsas, anotas hora y lugar cada vez y propones a administración un recordatorio general con horarios; al vecino le explicas que no se publican unidades","Publicas la unidad que señala el vecino para que no vuelva a pasar","Dejas las bolsas ahí hasta que el responsable las saque","Revisas el contenido de las bolsas para encontrar al responsable"],"correctIndex":0,"explanation":"Sin haberlo visto, publicar una unidad es exponer a alguien sin prueba. Revisar bolsas ajenas invade la privacidad y es riesgoso. El registro repetido permite a administración conversar en privado si es necesario."}},{"id":"residuos-comunicar","title":"Comunicar sin culpar","eyebrow":"Comunicación","layout":"comparison","lead":"Un buen aviso invita a cuidar el espacio común. Uno que acusa genera conflicto y no cambia la conducta.","bullets":["El aviso habla de la conducta y el horario: \"Recordamos que la sala de basura recibe bolsas cerradas en el horario publicado\".","Agradece y ofrece ayuda: dónde dejar voluminosos y a quién preguntar.","Si hay un caso concreto, lo conversa administración en privado.","No publiques fotos de bolsas con datos visibles ni números de unidad."],"visual_theme":"ink","notes":"Compara un aviso que acusa con uno que invita. Pide reescribir el primero manteniendo la información y quitando la culpa."},{"id":"residuos-cierre","title":"Antes de entregar el turno","eyebrow":"Transferencia","layout":"checklist","lead":"El turno queda bien entregado cuando la sala está ordenada y lo que se repite está anotado para administración.","bullets":["Contenedores dentro, limpios y con tapa.","Residuos especiales separados y avisados.","Hechos repetidos anotados para administración."],"visual_theme":"ink","notes":"Revisa la lista con la sala de basura del edificio y acuerda una mejora concreta para la próxima semana.","activity":{"type":"checklist","prompt":"Confirma que puedes aplicar estos pasos en tu turno:","items":["Sacar y ordenar los contenedores según el horario de retiro","Orientar la separación para reciclar según el gestor del edificio","Manejar residuos peligrosos y voluminosos con protección y avisar","Comunicar recordatorios generales sin exponer unidades ni personas"],"explanation":"Así los espacios comunes se mantienen limpios y la convivencia no se resiente."}}]$course$, 0),
  ('9f6a1b41-4e1b-4472-8b11-bf3b98600109', '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c109', 'Clase principal', $course$[{"id":"atencion-proposito","title":"Escuchar primero, resolver después","eyebrow":"Inicio","layout":"opening","lead":"Una buena atención baja la tensión, deja constancia y lleva el caso a quien puede resolverlo. La convivencia se construye en cada conversación.","bullets":["Quien atiende no decide quién tiene la razón: escucha, anota y deriva.","Siempre hay una salida: conversar, dejar constancia o derivar a administración.","Nadie queda expuesto: no se revela quién reclamó ni se comentan casos con otros vecinos."],"visual_theme":"ink","notes":"Pide recordar una conversación difícil con un residente y qué la empeoró o la calmó. Usa esas respuestas para presentar las secciones del curso."},{"id":"atencion-escuchar","title":"Escuchar y desescalar","eyebrow":"Conversación","layout":"process","lead":"La persona molesta necesita sentirse escuchada antes de escuchar una solución.","bullets":["Deja que la persona termine. Repite lo que entendiste: \"Me dice que el ruido empieza pasada la medianoche\".","Habla con voz baja y pausada. Reconoce la molestia sin dar la razón a nadie: \"Entiendo que así es difícil descansar\".","Ofrece un paso siguiente concreto: qué vas a anotar y a quién lo vas a derivar.","Si la persona grita o insulta, pide calma una vez y ofrece seguir más tarde o por escrito."],"visual_theme":"sage","notes":"Haz un juego de roles con un residente molesto. Detén el ejercicio si quien atiende interrumpe, discute o promete una solución que no le corresponde."},{"id":"atencion-imparcial","title":"No tomar partido","eyebrow":"Imparcialidad","layout":"comparison","lead":"Ser imparcial no es ser frío: es tratar igual a cada vecino y quedarse con los hechos.","bullets":["Anota hechos observables: hora, lugar y qué se escuchó o vio.","Escucha a cada parte por separado, con el mismo trato.","No digas quién reclamó ni repitas lo que dijo otro vecino.","Evita juicios: \"ese vecino siempre es así\" no es un dato."],"visual_theme":"copper","notes":"Lee dos frases de registro y pide marcar cuál es un hecho y cuál una opinión. Corrige cualquier frase que revele quién reclamó.","activity":{"type":"knowledge_check","prompt":"El vecino del 402 pregunta quién reclamó por el ruido de su fiesta. ¿Qué respondes?","options":["\"Fue la vecina del 302, pero no le diga que yo le conté\"","\"No puedo decirle quién avisó. Lo que sí le puedo contar es qué se anotó y que administración puede conversar con usted si lo necesita\"","\"Fueron varios, todos están molestos con usted\"","\"Nadie reclamó, era solo una sugerencia\""],"correctIndex":1,"explanation":"Proteger la identidad de quien avisa evita conflictos nuevos. Explicar qué se anotó y ofrecer conversar con administración da una salida sin exponer a nadie ni mentir."}},{"id":"atencion-derivar","title":"Dejar constancia y derivar a administración","eyebrow":"Derivación","layout":"framework","lead":"Lo que no queda escrito se pierde entre turnos. Lo que requiere una decisión va a quien puede tomarla.","bullets":["Todo reclamo queda en el sistema o en el libro de novedades: quién avisa, hora, hecho y qué se hizo.","Las solicitudes del libro de novedades se responden en un máximo de veinte días corridos (Ley 21.442, art. 17).","Deriva a administración lo que requiere decisión: aplicar el reglamento, conversar con las partes o proponer una mediación.","Informa a quien reclamó a quién se derivó y cuándo puede esperar respuesta, sin prometer un resultado."],"role_cards":[{"role":"Conserjería","responsibility":"Escucha y deja constancia","action":"Anota el hecho y deriva lo que requiere decisión"},{"role":"Administración","responsibility":"Decide y responde","action":"Conversa con las partes, aplica el reglamento y responde en plazo"}],"visual_theme":"ink","notes":"Pide derivar un caso de ruido reiterado: qué se anota, a quién se envía y qué se le dice al vecino que reclamó."},{"id":"atencion-casos","title":"Ruido, mascotas y estacionamientos","eyebrow":"Conflictos frecuentes","layout":"framework","lead":"Los conflictos más comunes entre vecinos tienen un primer paso claro. Si se repiten, pasan a administración con su historial.","bullets":["Ruido: anota hora y lugar. Puedes llamar a la unidad con un mensaje neutro: \"Nos llegó un aviso de ruido, ¿nos ayudan a bajarlo?\". No digas quién avisó.","Mascotas: el reglamento de copropiedad no puede prohibir tenerlas en la unidad, pero sí regular su uso de los espacios comunes (Ley 21.442, art. 8).","Estacionamientos: si un auto ocupa un lugar ajeno, busca a quien lo usa por el canal del edificio. No bloquees ni muevas vehículos por tu cuenta.","Un conflicto que se repite pasa a administración con todos los registros anteriores."],"visual_theme":"sage","notes":"Para cada caso, pide la primera frase que diría quien atiende. Revisa que sea neutra y no revele quién avisó.","activity":{"type":"knowledge_check","prompt":"Un residente exige que prohíban los perros en el edificio porque un perro ladra en el pasillo. ¿Qué le explicas?","options":["Que administración puede prohibir los perros desde mañana","Que no hay nada que hacer y debe acostumbrarse","Que el reglamento de copropiedad no puede prohibir tener mascotas en la unidad, pero sí regular su uso de los espacios comunes, y que anotarás el hecho para administración","Que vas a hablar con el dueño para que regale al perro"],"correctIndex":2,"explanation":"La Ley 21.442 (art. 8) impide prohibir las mascotas dentro de la unidad, pero permite reglas para los espacios comunes. Explicarlo y anotar el hecho da una salida real sin prometer lo que no corresponde."}},{"id":"atencion-escenario","title":"Discusión entre vecinos en el estacionamiento","eyebrow":"Práctica","layout":"scenario","lead":"En una discusión acalorada, el objetivo es bajar la tensión y separar a las partes, no decidir quién tiene la razón.","bullets":["Dos vecinos discuten a gritos porque uno estacionó en el lugar del otro.","Uno te pide que llames a la grúa de inmediato.","El otro dice que tú le diste permiso la semana pasada."],"visual_theme":"amber","notes":"Pide la secuencia exacta: qué se dice primero, a quién y qué se anota. La respuesta correcta separa, ofrece una salida y deriva.","activity":{"type":"scenario","prompt":"¿Qué haces?","options":["Llamas a la grúa porque el lugar tiene dueño","Le das la razón a quien te pidió permiso para no contradecirte","Te retiras para no meterte en problemas","Pides calma, hablas con cada uno por separado, propones mover el auto ahora como salida inmediata, anotas lo ocurrido y derivas a administración lo del permiso"],"correctIndex":3,"explanation":"Separar y ofrecer una salida inmediata baja la tensión. Lo que se discute sobre permisos o sanciones lo resuelve administración con el registro. Llamar a la grúa por tu cuenta o tomar partido escala el conflicto."}},{"id":"atencion-limites","title":"Los límites del rol","eyebrow":"Límites","layout":"comparison","lead":"Saber hasta dónde llega el rol protege a quien atiende y a la comunidad.","bullets":["Si hay agresión física o amenaza, llama a Carabineros al 133 y protégete.","Si un conflicto no se resuelve en la comunidad, la municipalidad puede atenderlo de forma extrajudicial cuando antes no se solucionó en la asamblea (Ley 21.442, art. 47).","No apliques sanciones ni decidas en el momento quién tiene la razón: eso sigue el reglamento y lo resuelve quien corresponde.","No te interpongas físicamente entre personas que pelean.","No compartas los datos de contacto de un vecino con otro sin su autorización."],"visual_theme":"copper","notes":"Pide ubicar tres situaciones en lo que hace quien atiende y lo que no: una amenaza, un pedido de teléfono de un vecino y una solicitud de multa."},{"id":"atencion-cierre","title":"Antes de cerrar un caso","eyebrow":"Transferencia","layout":"checklist","lead":"Un caso queda bien atendido cuando la persona sabe qué pasa ahora y el registro permite que otro lo continúe.","bullets":["La persona fue escuchada y sabe el paso siguiente.","Los hechos quedaron anotados sin opiniones.","Lo que requiere decisión está derivado a administración."],"visual_theme":"ink","notes":"Repasa la lista con el último caso atendido y acuerda qué se haría distinto la próxima vez.","activity":{"type":"checklist","prompt":"Confirma que puedes aplicar estos pasos:","items":["Escuchar hasta el final y repetir lo que entendiste","Anotar hechos con hora y lugar, sin opiniones ni nombres de quien avisa","Derivar a administración lo que requiere una decisión","Llamar al 133 si hay agresión o amenaza, sin interponerte"],"explanation":"Con estos pasos cada conflicto tiene una salida y nadie queda expuesto."}}]$course$, 0)
ON CONFLICT (id) DO UPDATE SET
  module_id = EXCLUDED.module_id,
  title = EXCLUDED.title,
