  ('7d3c2a10-6b1e-4f8a-9c55-2b0e5a9d0105'::uuid, '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c105'::uuid, '9f6a1b41-4e1b-4472-8b11-bf3b98600105'::uuid),
  ('7d3c2a10-6b1e-4f8a-9c55-2b0e5a9d0106'::uuid, '4b7f3d4b-5a7f-4c9b-a6c1-6ef2e7a8c106'::uuid, '9f6a1b41-4e1b-4472-8b11-bf3b98600106'::uuid),
